"""Private remote records, bounded reads and reviewed restore after history eviction."""
import json,time
from desktop_fixture import Peer,Desktop,expect,ROOT

out=ROOT/'artifacts/configuration-records-ui'
def record(group,identifier):
    return group.locator('.configuration-server-record').filter(has=group.page.get_by_text(identifier,exact=True))

with Peer(out/'peer-a') as a,Peer(out/'peer-b') as b:
    spec=dict(path="/srv/中文 ' site.conf",kind='Custom',service='',health_url='',expected_body='',health_seconds=3,validation='test -s "$1"',reload='true',health='true',sha256='a'*64)
    entries=[]
    for number in range(105):
        request=dict(spec=spec.copy(),restore_from=None)
        entry=dict(id=f'recovery-{number:04}',modified=1700000000+number,phase='published',path=spec['path'],kind='Custom',restore_from=None,service='inactive',issue=None,request=request,diff='--- current\n+++ original\n-current private fixture\n+original 中文 arcnix-test fixture-admin-secret\n')
        if number==104:entry['service']='active'
        if number==103:entry['service']='unavailable'
        if number==102:entry.update(phase='restored',restore_from='earlier-source');request['restore_from']='earlier-source'
        if number==101:entry['detail_issue']='Original backup is unavailable or does not match its digest'
        if number==100:entry.update(phase=None,path=None,kind=None,service='unknown',issue='Record metadata is unavailable or invalid')
        if number==99:entry['current_missing']=True
        entries.append(entry)
    (a.root/'configuration-records-fixture.json').write_text(json.dumps(entries),encoding='utf-8')
    alpha=a.profile('Alpha');alpha.update(username='arcnix-nosftp',auth='Password',private_key=None)
    config=a.config([alpha,b.profile('Beta')],out)
    host,port=b.data['address'].rsplit(':',1);config['config']['trusted_hosts'].append(dict(host=host,port=int(port),fingerprint=b.data['host_key_rsa_fingerprint']))
    with Desktop(out/f'desktop-{time.time_ns()}',config) as app:
        p=app.page;p.locator('.rail-configurations').click()
        p.get_by_role('textbox',name='Candidate configuration (UTF-8)',exact=True).fill('events {}\n# private source configuration\n')
        p.get_by_role('button',name='Review configuration on servers…',exact=True).click()
        d=p.get_by_role('dialog',name='Run script on servers',exact=True);d.locator('.target-choice').nth(1).click()
        d.get_by_role('button',name='Check targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Ready'],timeout=20000)
        p.get_by_role('button',name='Execute ready targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Succeeded'],timeout=20000)
        history=app.config.with_suffix('.tasks.json');source=json.loads(history.read_text())[0]['id']
        app.stop();history.unlink();app.launch();p=app.page;p.locator('.rail-configurations').click()
        expect(p.locator('.configuration-run')).to_have_count(0)
        p.get_by_role('button',name='Server recovery records',exact=True).click()
        d=p.get_by_role('dialog',name='Connect to recovery records',exact=True)
        d.get_by_role('button',name='Read recovery records',exact=True).click();expect(d.locator('.form-error')).to_be_visible()
        d.locator('.record-target').nth(0).click();d.locator('.record-target').nth(1).click()
        d.get_by_role('textbox',name='SSH password or key passphrase',exact=True).first.fill('arcnix-test')
        d.get_by_role('textbox',name='Administrator password (optional)',exact=True).first.fill('fixture-admin-secret')
        d.get_by_role('button',name='Read recovery records',exact=True).click()
        groups=p.locator('.configuration-record-group');expect(groups).to_have_count(2)
        alpha_group=groups.filter(has=p.get_by_text('Alpha',exact=True));beta_group=groups.filter(has=p.get_by_text('Beta',exact=True))
        expect(alpha_group.locator('.configuration-server-record')).to_have_count(100,timeout=20000)
        expect(beta_group.locator('.configuration-server-record')).to_have_count(1,timeout=20000)
        expect(alpha_group.locator('.recovery-capacity')).to_contain_text('105 records')
        expect(record(beta_group,source)).to_contain_text('Configuration published and health confirmed')
        for identifier,state in [('recovery-0104','Running'),('recovery-0103','Service state unavailable')]:
            record(alpha_group,identifier).get_by_role('button',name='Inspect recovery version…',exact=True).click()
            d=p.get_by_role('dialog',name='Server recovery version',exact=True)
            expect(d.locator('.recovery-detail-state')).to_have_text(state,timeout=20000)
            expect(d.get_by_role('button',name='Review restoration…',exact=True)).to_be_disabled()
            d.get_by_role('button',name='Close',exact=True).click()
        for identifier in ['recovery-0102','recovery-0101','recovery-0100']:
            record(alpha_group,identifier).get_by_role('button',name='Inspect recovery version…',exact=True).click()
            d=p.get_by_role('dialog',name='Server recovery version',exact=True)
            if identifier.endswith('0100'):expect(d.locator('.form-error')).to_be_visible(timeout=20000)
            else:expect(d.locator('.recovery-detail-phase')).not_to_have_text('Reading recovery version…',timeout=20000)
            expect(d.get_by_role('button',name='Review restoration…',exact=True)).to_be_disabled()
            d.get_by_role('button',name='Close',exact=True).click()
        record(alpha_group,'recovery-0099').get_by_role('button',name='Inspect recovery version…',exact=True).click()
        d=p.get_by_role('dialog',name='Server recovery version',exact=True)
        expect(d.locator('.recovery-missing')).to_contain_text('Current configuration is missing',timeout=20000)
        expect(d.get_by_role('button',name='Review restoration…',exact=True)).to_be_enabled()
        d.get_by_role('button',name='Close',exact=True).click()
        alpha_group.get_by_role('button',name='Older records',exact=True).click();expect(alpha_group.locator('.configuration-server-record')).to_have_count(5,timeout=20000)
        record(alpha_group,'recovery-0000').get_by_role('button',name='Inspect recovery version…',exact=True).click()
        d=p.get_by_role('dialog',name='Server recovery version',exact=True)
        expect(d.locator('.recovery-diff')).to_contain_text('original 中文 [redacted] [redacted]',timeout=20000)
        expect(d.locator('.recovery-logs')).to_contain_text('private log · [redacted] · [redacted]')
        expect(d.locator('.recovery-detail-server')).to_contain_text('Alpha · arcnix-nosftp@127.0.0.1:')
        expect(d.locator('.recovery-review')).to_contain_text('Restore the original server backup')
        app.screenshot('private-version.png')
        (a.root/'configuration-records-truncated').touch();d.get_by_role('button',name='Refresh recovery version',exact=True).click()
        expect(d.locator('.form-error')).to_be_visible(timeout=20000)
        expect(d.locator('.recovery-diff')).to_contain_text('original 中文 [redacted] [redacted]')
        expect(d.get_by_role('button',name='Review restoration…',exact=True)).to_be_disabled()
        (a.root/'configuration-records-truncated').unlink();d.get_by_role('button',name='Refresh recovery version',exact=True).click()
        expect(d.get_by_role('button',name='Review restoration…',exact=True)).to_be_enabled(timeout=20000)
        d.get_by_role('button',name='Close',exact=True).click()
        assert not history.exists(),'Read-only record browsing must not recreate task history'
        saved=app.config.read_text();assert all(text not in saved for text in ['private fixture','private source configuration','arcnix-test','fixture-admin-secret'])
        snapshot=beta_group.locator('.recovery-snapshot').inner_text()
        (b.root/'configuration-records-truncated').touch();beta_group.get_by_role('button',name='Refresh records',exact=True).click()
        expect(beta_group.locator('.form-error')).to_be_visible(timeout=20000)
        expect(beta_group.locator('.configuration-server-record')).to_have_count(1);expect(beta_group.locator('.recovery-snapshot')).to_have_text(snapshot)
        (b.root/'configuration-records-truncated').unlink();(b.root/'configuration-records-root-changed').touch()
        beta_group.get_by_role('button',name='Refresh records',exact=True).click();expect(beta_group.locator('.form-error')).to_contain_text('does not match',timeout=20000)
        (b.root/'configuration-records-root-changed').unlink();beta_group.get_by_role('button',name='Refresh records',exact=True).click();expect(beta_group.locator('.form-error')).to_have_count(0,timeout=20000)
        (a.root/'configuration-records-incomplete-capacity').touch();alpha_group.get_by_role('button',name='Refresh records',exact=True).click()
        expect(alpha_group).to_contain_text('Capacity is incomplete',timeout=20000)
        (b.root/'configuration-records-wrong-id').touch();record(beta_group,source).get_by_role('button',name='Inspect recovery version…',exact=True).click()
        d=p.get_by_role('dialog',name='Server recovery version',exact=True);expect(d.locator('.form-error')).to_contain_text('does not match',timeout=20000)
        expect(d.get_by_role('button',name='Review restoration…',exact=True)).to_be_disabled()
        (b.root/'configuration-records-wrong-id').unlink();d.get_by_role('button',name='Refresh recovery version',exact=True).click()
        expect(d.locator('.recovery-diff')).to_contain_text('fixture previous version',timeout=20000)
        d.get_by_role('button',name='Review restoration…',exact=True).click()
        d=p.get_by_role('dialog',name='Run script on servers',exact=True)
        expect(d.locator('.target-choice.active')).to_have_count(1);expect(d.locator('.target-choice.active')).to_contain_text('Beta')
        expect(d).to_contain_text('Restore the original server backup')
        assert not history.exists(),'Opening a restore review must not submit a task'
        d.get_by_role('button',name='Check targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Ready'],timeout=20000)
        expect(p.locator('.configuration-diff')).to_contain_text('fixture previous version')
        p.get_by_role('button',name='Execute ready targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Succeeded'],timeout=20000)
        tasks=json.loads(history.read_text());assert len(tasks)==1 and tasks[0]['configuration']['restore_from']==source and tasks[0]['targets'][0]['id']=='Beta'
        assert 'fixture previous version' not in history.read_text()
        p.locator('.rail-configurations').click();expect(beta_group.get_by_role('button',name='Refresh records',exact=True)).to_be_disabled()
        p.get_by_role('button',name='Connect to recovery records…',exact=True).click();d=p.get_by_role('dialog',name='Connect to recovery records',exact=True)
        expect(d.get_by_role('textbox',name='Administrator password (optional)',exact=True).first).to_have_value('')
        d.get_by_role('button',name='Cancel',exact=True).click()
        saved_history=history.read_text()
        def reconnect():
            p.get_by_role('button',name='Connect to recovery records…',exact=True).click()
            d=p.get_by_role('dialog',name='Connect to recovery records',exact=True)
            expect(d.get_by_role('textbox',name='SSH password or key passphrase',exact=True).first).to_have_value('')
            expect(d.get_by_role('textbox',name='Administrator password (optional)',exact=True).first).to_have_value('')
            d.get_by_role('textbox',name='SSH password or key passphrase',exact=True).first.fill('arcnix-test')
            d.get_by_role('textbox',name='Administrator password (optional)',exact=True).first.fill('fixture-admin-secret')
            d.get_by_role('button',name='Read recovery records',exact=True).click()
            expect(alpha_group).to_contain_text('Record browser connected',timeout=20000)
            expect(beta_group).to_contain_text('Record browser connected',timeout=20000)
            expect(beta_group.locator('.configuration-server-record')).to_have_count(2,timeout=20000)
        reconnect()
        p.get_by_role('button',name='Forget recovery credentials',exact=True).click()
        expect(beta_group.get_by_role('button',name='Refresh records',exact=True)).to_be_disabled()
        reconnect()
        app.settings('General');p.get_by_role('button',name='简体中文',exact=True).click();expect(p.locator('.page-header-title')).to_have_text('常规')
        p.locator('.rail-configurations').click();expect(p.locator('.page-header-title')).to_have_text('配置发布')
        expect(beta_group.get_by_role('button',name='刷新记录',exact=True)).to_be_disabled()
        assert history.read_text()==saved_history,'Repeated record reads must not modify saved task results'
        p.set_viewport_size(dict(width=900,height=700));assert p.evaluate('document.documentElement.scrollWidth <= innerWidth');app.screenshot('records-chinese.png')
        p.get_by_role('button',name='最近的配置变更',exact=True).click()
        expect(p.locator('.configuration-phase')).to_have_text(['记录版本已恢复，健康检查已确认'])

checks=['global browser without selected workspace','multiple pinned servers','password and sudo stdin without SFTP','history evicted before record discovery','publication recovered from server metadata','bounded pagination reaches older versions','root record capacity summary','partial capacity is explicit','active source cannot restore','unknown service cannot restore','restore record cannot be reused as original','missing original blocks restore','invalid metadata cannot restore','missing current target retains reviewed restore','private diff and logs redact both credentials','read-only browsing writes no local history','failed refresh preserves snapshot','failed detail refresh preserves data but blocks restore','changed root is rejected','detail identity mismatch is rejected','refresh does not execute saved commands','restore preselects original server','restore requires new authenticated preview','server-backed restore succeeds without original local batch','content excluded from persisted restore history','credentials cleared on task submission','reconnect fields are empty','forgetting disables new queries','navigation clears active credentials','Chinese narrow layout']
(out/'results.json').write_text(json.dumps(dict(passed=True,checks=checks),indent=2))
print(f'{len(checks)} configuration record UI checks passed')
